package truth

// Purpose: find the spans of a file a claim rule must not judge: generated
// regions, JSX expressions, Astro code, lines under a `truth: exempt` comment.
// Inputs:  a file's repo-relative path and its lines.
// Outputs: a fileMask answering "is this match exempt?" and listing the
// `truth: exempt` comments that carry no reason.
// Constraints: Epic TRUTH D6. A region is exempt only when both its markers are
// present (an unclosed `BEGIN GENERATED` exempts nothing); the first three lines
// holding `GENERATED BY` exempt the whole file; JSX expressions count only in
// .astro and .mdx, only when the braces balance, and never inside a code fence;
// an .astro file's frontmatter, <script> and <style> blocks are code, not prose;
// the exempt comment covers the next line only; no file or network access.

import (
	"regexp"
	"strings"
)

var (
	beginRe  = regexp.MustCompile(`<!--\s*BEGIN GENERATED:([A-Za-z0-9._-]+)\s*-->`)
	endRe    = regexp.MustCompile(`<!--\s*END GENERATED:([A-Za-z0-9._-]+)\s*-->`)
	exemptRe = regexp.MustCompile(`<!--\s*truth:\s*exempt\b(.*?)-->`)
)

// fileMask is the exempt part of one file.
type fileMask struct {
	whole    []bool   // line i (0-based) is exempt as a whole
	all      bool     // the whole file is exempt (GENERATED BY header)
	starts   []int    // byte offset of each line in the joined text
	spans    [][2]int // JSX expression spans as byte offsets in the joined text
	NoReason []int    // 1-based lines of `truth: exempt` comments without a reason
}

// analyze computes the mask of one file.
func analyze(rel string, lines []string) fileMask {
	m := fileMask{whole: make([]bool, len(lines)), starts: make([]int, len(lines))}
	off := 0
	for i, l := range lines {
		m.starts[i] = off
		off += len(l) + 1
	}
	for i := 0; i < len(lines) && i < 3; i++ {
		if strings.Contains(lines[i], "GENERATED BY") {
			m.all = true
		}
	}
	m.generatedRegions(lines)
	m.exemptComments(lines)
	ext := strings.ToLower(rel[strings.LastIndex(rel, ".")+1:])
	if strings.HasSuffix(rel, ".astro") || ext == "mdx" {
		m.jsx(lines, ext == "astro")
	}
	return m
}

func (m *fileMask) generatedRegions(lines []string) {
	for i := 0; i < len(lines); i++ {
		g := beginRe.FindStringSubmatch(lines[i])
		if g == nil {
			continue
		}
		for j := i + 1; j < len(lines); j++ {
			if e := endRe.FindStringSubmatch(lines[j]); e != nil && e[1] == g[1] {
				for k := i; k <= j; k++ {
					m.whole[k] = true
				}
				i = j
				break
			}
		}
	}
}

func (m *fileMask) exemptComments(lines []string) {
	for i, l := range lines {
		g := exemptRe.FindStringSubmatch(l)
		if g == nil {
			continue
		}
		if strings.TrimSpace(g[1]) == "" {
			m.NoReason = append(m.NoReason, i+1)
			continue
		}
		if i+1 < len(lines) {
			m.whole[i+1] = true
		}
	}
}

// jsx marks Astro code blocks and brace expressions.
func (m *fileMask) jsx(lines []string, astro bool) {
	fence, depth, open := false, 0, 0
	inFront, inCode := false, ""
	for i, l := range lines {
		t := strings.TrimSpace(l)
		if astro {
			if i == 0 && t == "---" {
				inFront = true
				m.whole[i] = true
				continue
			}
			if inFront {
				m.whole[i] = true
				inFront = t != "---"
				continue
			}
			if inCode != "" {
				m.whole[i] = true
				if strings.Contains(strings.ToLower(l), "</"+inCode) {
					inCode = ""
				}
				continue
			}
			for _, tag := range []string{"script", "style"} {
				low := strings.ToLower(l)
				if p := strings.Index(low, "<"+tag); p >= 0 && !strings.Contains(low[p:], "</"+tag) {
					inCode = tag
					m.whole[i] = true
				}
			}
			if inCode != "" {
				continue
			}
		}
		if strings.HasPrefix(t, "```") || strings.HasPrefix(t, "~~~") {
			fence = !fence
			continue
		}
		if fence {
			continue
		}
		for c := 0; c < len(l); c++ {
			switch l[c] {
			case '{':
				if depth == 0 {
					open = m.starts[i] + c
				}
				depth++
			case '}':
				if depth > 0 {
					depth--
					if depth == 0 {
						m.spans = append(m.spans, [2]int{open, m.starts[i] + c + 1})
					}
				}
			}
		}
	}
}

// exempt reports whether the hit [start,end) on 0-based line i is inside an exempt part.
func (m fileMask) exempt(i, start, end int) bool {
	if m.all || m.whole[i] {
		return true
	}
	s, e := m.starts[i]+start, m.starts[i]+end
	for _, sp := range m.spans {
		if sp[0] <= s && e <= sp[1] {
			return true
		}
	}
	return false
}
